<?php require_once __DIR__.'/../config/bootstrap.php';$msg='';$dev='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$s=db()->prepare('SELECT id,nome,email FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u){$raw=bin2hex(random_bytes(32));db()->prepare('DELETE FROM password_resets WHERE user_id=?')->execute([$u['id']]);db()->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))')->execute([$u['id'],hash('sha256',$raw)]);$link=app_base_url().'/aluno/redefinir-senha.php?token='.$raw;if(!send_reset_email($u['email'],$u['nome'],$link) && APP_ENV==='local')$dev=$link;}$msg='Se o e-mail estiver cadastrado, enviaremos as instruções de redefinição.';} ?>
<?php layout_header('Recuperar senha'); ?><div class="auth-card"><h1>Recuperar senha</h1><p class="subtitle">Informe o e-mail cadastrado.</p><?php if($msg): ?><div class="notice success"><?=e($msg)?></div><?php endif; ?><form method="post"><?=csrf_field()?><label>E-mail</label><input type="email" name="email" required><button class="btn">Enviar link</button></form><?php if($dev): ?><div class="dev-box"><strong>Ambiente local:</strong><br>Como o XAMPP normalmente não vem com SMTP configurado, use este link para testar:<br><a href="<?=e($dev)?>"><?=e($dev)?></a></div><?php endif; ?></div><?php layout_footer(); ?>
